import React, { useState, useRef, useEffect } from 'react';
import { Link } from 'react-router-dom';
import { courses } from '../data/courses';
import PaymentModal from '../components/paymentModal';
import Navbar from '../components/Navbar';

const Home = () => {
  const [selectedCourse, setSelectedCourse] = useState(null);
  const searchRef = useRef(null);

  useEffect(() => {
    const handleKey = (e) => { if (e.key === '/') { e.preventDefault(); searchRef.current?.focus(); } };
    window.addEventListener('keydown', handleKey);
    return () => window.removeEventListener('keydown', handleKey);
  }, []);

  return (
    <div className="min-h-screen bg-[#0A0E1A] text-white font-sans">
      <Navbar />

      {/* HERO */}
      <section className="relative overflow-hidden border-b border-slate-800/60">
        <div className="absolute top-0 left-1/2 -translate-x-1/2 w-[600px] h-[300px] bg-blue-600/20 blur-[120px] rounded-full pointer-events-none"></div>
        <div className="relative max-w-4xl mx-auto text-center px-6 py-24">
          <span className="inline-block text-[11px] font-semibold tracking-wide text-blue-400 bg-blue-500/10 border border-blue-500/20 rounded-full px-4 py-1.5 mb-8">
            Écosystème académique international
          </span>
          <h1 className="text-4xl md:text-6xl font-extrabold leading-tight mb-6">
            Déployez vos compétences d'élite avec<br />
            <span className="bg-gradient-to-r from-blue-400 to-cyan-300 bg-clip-text text-transparent">
              Avalon Secure Academy
            </span>
          </h1>
          <p className="text-slate-400 max-w-xl mx-auto mb-10 text-base leading-relaxed">
            Accédez à un contenu d'ingénierie réseau et de cyberdéfense de classe mondiale, conçu par des professionnels du secteur.
          </p>

          <div className="flex flex-col sm:flex-row items-center justify-center gap-3 mb-10">
            <Link to="/catalog" className="w-full sm:w-auto bg-blue-600 hover:bg-blue-500 text-white font-semibold px-8 py-3.5 rounded-lg transition-colors shadow-lg shadow-blue-600/20">
              Explorer les formations
            </Link>
            <Link to="/contact" className="w-full sm:w-auto bg-slate-800/60 hover:bg-slate-800 border border-slate-700 text-slate-200 font-semibold px-8 py-3.5 rounded-lg transition-colors">
              <a
                 href="https://mail.google.com/mail/?view=cm&fs=1&to=TON-EMAIL@gmail.com&su=Contact%20Avalon%20Secure%20Academy"
                  target="_blank"
                  rel="noopener noreferrer"
                  className="w-full sm:w-auto bg-slate-800/60 hover:bg-slate-800 border border-slate-700 text-slate-200 font-semibold px-8 py-3.5 rounded-lg transition-colors"
                  >
                  Nous contacter
                  </a>
            </Link>
          </div>

          <div className="relative max-w-md mx-auto">
            <input
              ref={searchRef}
              placeholder="Rechercher une formation..."
              className="w-full bg-slate-900/80 border border-slate-700 rounded-full pl-5 pr-12 py-3 text-sm text-white placeholder:text-slate-500 outline-none focus:border-blue-500 transition-colors"
            />
            <span className="absolute right-4 top-1/2 -translate-y-1/2 text-[10px] text-slate-500 border border-slate-700 rounded px-1.5 py-0.5">/</span>
          </div>
        </div>
      </section>

      {/* COURSE GRID */}
      <section className="max-w-6xl mx-auto px-6 py-20">
        <div className="flex items-center justify-between mb-10">
          <h2 className="text-2xl font-bold">Programmes d'apprentissage</h2>
          <Link to="/catalog" className="text-sm font-semibold text-blue-400 hover:text-blue-300 transition-colors">
            Voir tout le catalogue →
          </Link>
        </div>

        <div className="grid md:grid-cols-3 gap-6">
          {courses.map(course => (
            <div key={course.id} className="group bg-slate-900/60 border border-slate-800 rounded-2xl p-7 flex flex-col justify-between hover:border-blue-500/40 hover:bg-slate-900 transition-all duration-300 shadow-xl">
              <div>
                <div className="flex items-center justify-between mb-5">
                  <span className={`text-[11px] font-bold uppercase tracking-wide px-3 py-1 rounded-full ${
                    course.isFree ? 'bg-emerald-500/10 text-emerald-400' : 'bg-blue-500/10 text-blue-400'
                  }`}>
                    {course.isFree ? 'Gratuit' : 'Premium'}
                  </span>
                  <span className="text-xs font-mono text-slate-500">
                    {course.isFree ? '0 FCFA' : `${course.price.toLocaleString()} FCFA`}
                  </span>
                </div>
                <h3 className="text-lg font-bold mb-3 leading-snug group-hover:text-blue-400 transition-colors">
                  {course.title}
                </h3>
                <p className="text-slate-400 text-sm leading-relaxed mb-8">{course.description}</p>
              </div>
              <div className="flex gap-3">
                <Link to={`/course/${course.id}`} className="flex-1 text-center border border-slate-700 hover:border-slate-500 text-slate-300 hover:text-white font-semibold py-3 rounded-lg text-sm transition-colors">
                  Détails
                </Link>
                <button onClick={() => setSelectedCourse(course)} className="flex-1 bg-blue-600 hover:bg-blue-500 text-white font-semibold py-3 rounded-lg text-sm transition-colors">
                  {course.isFree ? 'Accéder' : 'Débloquer'}
                </button>
              </div>
            </div>
          ))}
        </div>
      </section>

      {selectedCourse && <PaymentModal course={selectedCourse} onClose={() => setSelectedCourse(null)} />}
    </div>
  );
};
export default Home;
